questions.sol_text:
θ = {
  2π + 4 tan⁻¹ x,     x ∈ (-∞, -tan(3π/8)]
  π + 4 tan⁻¹ x,      x ∈ (-tan(3π/8), -tan(π/8)]
  4 tan⁻¹ x,          x ∈ (-tan(π/8), tan(π/8)]
  -π + 4 tan⁻¹ x,     x ∈ (tan(π/8), tan(3π/8)]
  -2π + 4 tan⁻¹ x,    x ∈ (tan(3π/8), ∞)
}

φ = {
  -2π - 4 tan⁻¹ x,    x ∈ (-∞, -1]
  4 tan⁻¹ x,          x ∈ (-1, 1]
  2π - 4 tan⁻¹ x,     x ∈ (1, ∞)
}

φ - θ = π for x ∈ (tan(π/8), 1)
